import { Component, ElementRef, EventEmitter, Input, Output, ViewChild, AfterViewInit, OnChanges, SimpleChanges } from '@angular/core';
import { CommonModule } from '@angular/common';
import { AppIconComponent } from '../icons/app-icon.component';

@Component({
    selector: 'app-rich-text-editor',
    standalone: true,
    imports: [CommonModule, AppIconComponent],
    template: `
    <div class="relative flex flex-col border border-[#ccc] rounded-md overflow-hidden bg-white shadow-sm w-full">
      
      <!-- Reply Preview -->
      <div *ngIf="replyTo" class="mx-4 mt-4 mb-0 p-4 flex flex-col gap-2 rounded bg-[#E7F8FB] border border-[#007A91] relative group/reply min-w-0">
          <div class="flex items-start justify-between min-w-0">
              <div class="flex-1 min-w-0 pr-10">
                  <div class="flex items-center justify-between mb-2">
                      <span class="text-[#262626] text-sm font-bold">{{ replyTo.sender }}</span>
                      <span class="text-[#666] text-xs">{{ replyTo.timestamp }}</span>
                  </div>
                  <div class="text-[#262626] text-sm opacity-90 break-words whitespace-pre-wrap transition-all duration-300 composer-scrollbar"
                       style="overflow-wrap: anywhere;"
                       [style.max-height]="isPreviewExpanded ? '150px' : '40px'"
                       [style.overflow-y]="isPreviewExpanded ? 'auto' : 'hidden'"
                       [ngClass]="isPreviewExpanded ? '' : 'line-clamp-2'"
                       [innerHTML]="replyTo.content">
                  </div>
              </div>
              <button (click)="cancelReply.emit(); isPreviewExpanded = false" class="text-[#007A91] hover:text-[#005a6b] transition-colors p-0.5 absolute top-4 right-4 z-10">
                  <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
              </button>
          </div>
          <!-- Read More for Preview -->
          <button *ngIf="shouldShowReadMore(replyTo.content)" 
                  (click)="isPreviewExpanded = !isPreviewExpanded"
                  class="flex items-center gap-1 text-[#007A91] text-[10px] font-bold uppercase mt-1 self-end hover:opacity-80 transition-opacity">
              {{ isPreviewExpanded ? 'Read Less' : 'Read More' }}
          </button>
      </div>
      
      <!-- Toolbar -->
      <div *ngIf="showToolbar || !isEmpty" class="flex items-center gap-0.5 px-2 py-1.5 border-b border-[#e6e6e6] bg-white overflow-x-auto no-scrollbar">
        <!-- Paste -->
        <button (click)="execCommand('paste')" class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]" title="Paste">
            <app-icon name="paste" size="18"></app-icon>
        </button>
        
        <div class="w-px h-6 bg-[#e6e6e6] mx-1"></div>

        <!-- Font Size (Simple Dropdown Mimic) -->
        <div class="relative group">
            <button class="flex items-center gap-1.5 px-2 py-1 hover:bg-[#f5f5f5] rounded text-sm cursor-pointer transition-colors outline-none">
                <span class="text-[#262626] font-medium">{{ fontSize }}</span>
                <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" class="text-[#666]" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg>
            </button>
            <div class="absolute top-full left-0 hidden group-hover:block bg-white border border-[#e6e6e6] shadow-lg rounded-[4px] z-10 min-w-[60px] p-1">
                <div *ngFor="let size of ['14', '16', '18', '20']" 
                     (click)="setFontSize(size)"
                     class="px-3 py-1.5 hover:bg-[#e7f8fb] cursor-pointer text-sm text-[#262626] rounded-sm">
                     {{ size }}
                </div>
            </div>
        </div>

        <div class="w-px h-6 bg-[#e6e6e6] mx-1"></div>

        <!-- Bold -->
        <button (click)="execCommand('bold')" 
                [class.bg-[#e7f8fb]]="isBold" [class.text-[#007a91]]="isBold"
                class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]">
          <app-icon name="bold" size="18"></app-icon>
        </button>

        <!-- Italic -->
        <button (click)="execCommand('italic')" 
                [class.bg-[#e7f8fb]]="isItalic" [class.text-[#007a91]]="isItalic"
                class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]">
          <app-icon name="italic" size="18"></app-icon>
        </button>

        <!-- Underline -->
        <button (click)="execCommand('underline')" 
                [class.bg-[#e7f8fb]]="isUnderline" [class.text-[#007a91]]="isUnderline"
                class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]">
          <app-icon name="underline" size="18"></app-icon>
        </button>
      </div>

      <!-- Editor Area -->
      <div #editor
           contentEditable="true"
           class="w-full px-4 py-[10px] bg-white focus:outline-none transition-colors composer-scrollbar overflow-y-auto rich-text-content break-words whitespace-pre-wrap"
           [style.min-height]="showToolbar ? '100px' : '44px'"
           [style.max-height]="'140px'"
           (input)="onInput()"
           (focus)="onFocus()"
           (blur)="onBlur()"
           (keydown)="onKeyDown($event)">
      </div>

      <!-- Placeholder -->
      <div *ngIf="isEmpty && !isFocused" 
           class="absolute left-4 text-[#666] pointer-events-none select-none z-10"
           [style.top]="placeholderTop">
          {{ placeholder }}
      </div>

    </div>
  `,
    styles: [`
    .rich-text-content {
      word-break: break-word;
      overflow-wrap: anywhere;
      line-height: 1.5;
    }
  `]
})
export class RichTextEditorComponent implements AfterViewInit, OnChanges {
    @Input() placeholder: string = 'Type your message...';
    @Input() content: string = '';
    @Input() showToolbar: boolean = false;
    @Input() maxHeight: string = '200px';
    @Input() replyTo: any = null;
    @Output() contentChange = new EventEmitter<string>();
    @Output() enterPressed = new EventEmitter<void>();
    @Output() cancelReply = new EventEmitter<void>();

    isPreviewExpanded = false;

    @ViewChild('editor') editorRef!: ElementRef<HTMLDivElement>;

    fontSize = '14';
    isBold = false;
    isItalic = false;
    isUnderline = false;
    isFocused = false;
    isEmpty: boolean = true;

    get placeholderTop(): string {
        if (this.replyTo) {
            // Placeholder top shifts significantly when replying
            const base = this.showToolbar ? 52 : 10;
            const replyHeight = this.isPreviewExpanded ? 150 : 80; // Rough estimates
            return (base + replyHeight) + 'px';
        }
        return this.showToolbar ? '52px' : '10px';
    }

    shouldShowReadMore(content: string | undefined): boolean {
        if (!content) return false;
        return content.length > 150 || content.includes('<br>') || content.includes('</div>');
    }

    private updateIsEmpty() {
        if (!this.editorRef) {
            this.isEmpty = !this.content;
            return;
        }
        const html = this.editorRef.nativeElement.innerHTML || '';
        const text = this.editorRef.nativeElement.innerText || '';
        // Robust check for empty content
        this.isEmpty = !html || html === '<br>' || html === '<div><br></div>' || text.trim() === '';
    }

    ngAfterViewInit() {
        if (this.content && this.editorRef) {
            this.editorRef.nativeElement.innerHTML = this.content;
        }
        this.updateIsEmpty();
    }

    ngOnChanges(changes: SimpleChanges) {
        if (changes['content']) {
            if (this.editorRef && this.content !== this.editorRef.nativeElement.innerHTML) {
                this.editorRef.nativeElement.innerHTML = this.content || '';
                this.checkActiveStyles();
                this.updateIsEmpty();
            } else if (!this.editorRef) {
                this.isEmpty = !this.content;
            }
        }
    }

    onInput() {
        if (this.editorRef) {
            this.contentChange.emit(this.editorRef.nativeElement.innerHTML);
            this.checkActiveStyles();
            this.updateIsEmpty();
        }
    }

    onFocus() {
        this.isFocused = true;
        this.showToolbar = true;
        this.checkActiveStyles();
    }

    onBlur() {
        setTimeout(() => {
            this.isFocused = false;
        }, 200);
    }

    onKeyDown(event: KeyboardEvent) {
        if (event.key === 'Enter' && !event.shiftKey) {
            event.preventDefault();
            this.enterPressed.emit();
        }
    }

    execCommand(command: string, value: string | any = null) {
        document.execCommand(command, false, value);
        this.checkActiveStyles();
        this.onInput();
    }

    setFontSize(size: string) {
        this.fontSize = size;
        const sizeMap: Record<string, string> = { '14': '1', '16': '2', '18': '3', '20': '4' };
        this.execCommand('fontSize', sizeMap[size] || '1');
    }

    checkActiveStyles() {
        this.isBold = document.queryCommandState('bold');
        this.isItalic = document.queryCommandState('italic');
        this.isUnderline = document.queryCommandState('underline');
    }

    public clear() {
        if (this.editorRef) {
            this.editorRef.nativeElement.innerHTML = '';
            this.onInput();
        }
    }

    public focus() {
        this.editorRef?.nativeElement?.focus();
    }
}
